-- =====================================================================
-- Spazio Design · Cotizador · Recetas de los modelos de la web
-- Generado por scripts/cotizador/recetas_catalogo.py. Crea los productos que falten y
-- publica cada receta como versión nueva solo si cambió. Se puede correr de nuevo.
-- Se ejecuta después de 2026-10_componentes.sql y 2026-10_recetas_piloto.sql.
-- =====================================================================

create or replace function pg_temp.publicar_receta(p_nombre text, p_categoria text, p_def jsonb, p_nota text) returns text
language plpgsql as $$
declare
  v_prod uuid;
  v_pub public.cot_recetas%rowtype;
  v_bor uuid;
  v_id uuid;
  v_ver integer;
begin
  select id into v_prod from public.cot_productos where lower(nombre) = lower(p_nombre) and activo;
  if v_prod is null then
    insert into public.cot_productos (nombre, categoria_id)
    values (p_nombre, (select id from public.cot_categorias where nombre = p_categoria))
    returning id into v_prod;
  end if;
  select * into v_pub from public.cot_recetas where producto_id = v_prod and estado = 'publicada';
  if found and v_pub.definicion = p_def then return p_nombre || ': sin cambios'; end if;
  if found then update public.cot_recetas set estado = 'archivada' where id = v_pub.id; end if;
  select id into v_bor from public.cot_recetas where producto_id = v_prod and estado = 'borrador';
  if v_bor is not null then
    update public.cot_recetas set definicion = p_def, nota = p_nota where id = v_bor;
    update public.cot_recetas set estado = 'publicada', publicado_en = now() where id = v_bor;
    v_id := v_bor;
  else
    select coalesce(max(version), 0) + 1 into v_ver from public.cot_recetas where producto_id = v_prod;
    insert into public.cot_recetas (producto_id, version, estado, definicion, nota, publicado_en)
    values (v_prod, v_ver, 'publicada', p_def, p_nota, now()) returning id into v_id;
  end if;
  update public.cot_productos set receta_publicada_id = v_id where id = v_prod;
  insert into public.cot_receta_insumos (receta_id, insumo_id)
  select v_id, i.id from public.cot_insumos i
  where p_def::text like '%''' || i.codigo || '''%' or p_def::text like '%"' || i.codigo || '"%'
  on conflict do nothing;
  select version into v_ver from public.cot_recetas where id = v_id;
  return p_nombre || ': publicada la versión ' || v_ver;
end $$;

select pg_temp.publicar_receta('Mesa Tierra', 'Mesas ratonas', '{"orden": ["L", "P", "H", "color"], "entradas": {"L": {"tipo": "medida", "nombre": "Largo", "def": 100}, "P": {"tipo": "medida", "nombre": "Profundidad", "def": 50}, "H": {"tipo": "medida", "nombre": "Alto", "def": 40}, "color": {"tipo": "opcion", "nombre": "Color", "atributo": "color", "def": "incoloro"}}, "lineas": [{"id": "tapa", "nombre": "Tapa", "regla": "m2", "insumoFormula": "si(en(color, ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')", "variante": {"espesor": "''10''", "composicion": "''5+5''", "color": "color"}, "ancho": "L", "largo": "P"}, {"id": "laterales", "nombre": "Laterales", "regla": "m2", "insumoFormula": "si(en(color, ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')", "variante": {"espesor": "''10''", "composicion": "''5+5''", "color": "color"}, "ancho": "P", "largo": "H - 1", "cantidad": "2"}, {"id": "uv", "nombre": "Pegado UV", "regla": "ml", "insumo": "pegado-uv", "variante": {"tipo_vidrio": "si(en(color, ''incoloro'', ''gris'', ''bronce''), ''float'', ''laminado'')"}, "metros": "(2 * P) / 100"}]}'::jsonb, 'Sin ajuste (20/10/2026)');
select pg_temp.publicar_receta('Mesa Tierra con Estante', 'Mesas ratonas', '{"orden": ["L", "P", "H", "color"], "entradas": {"L": {"tipo": "medida", "nombre": "Largo", "def": 100}, "P": {"tipo": "medida", "nombre": "Profundidad", "def": 50}, "H": {"tipo": "medida", "nombre": "Alto", "def": 40}, "color": {"tipo": "opcion", "nombre": "Color", "atributo": "color", "def": "incoloro"}}, "lineas": [{"id": "tapa", "nombre": "Tapa", "regla": "m2", "insumoFormula": "si(en(color, ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')", "variante": {"espesor": "''10''", "composicion": "''5+5''", "color": "color"}, "ancho": "L", "largo": "P"}, {"id": "laterales", "nombre": "Laterales", "regla": "m2", "insumoFormula": "si(en(color, ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')", "variante": {"espesor": "''10''", "composicion": "''5+5''", "color": "color"}, "ancho": "P", "largo": "H - 1", "cantidad": "2"}, {"id": "estante", "nombre": "Estante", "regla": "m2", "insumoFormula": "si(en(color, ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')", "variante": {"espesor": "''10''", "composicion": "''5+5''", "color": "color"}, "ancho": "L - 2", "largo": "P"}, {"id": "uv", "nombre": "Pegado UV", "regla": "ml", "insumo": "pegado-uv", "variante": {"tipo_vidrio": "si(en(color, ''incoloro'', ''gris'', ''bronce''), ''float'', ''laminado'')"}, "metros": "(4 * P) / 100"}]}'::jsonb, 'Sin ajuste, como la Tierra');
